set -euo pipefail
cat > src/core/config/test-env.ts <<'EOF'
/** Test-only environment mutation helper kept inside the Configuration layer. */
export async function withTemporaryEnvironment<T>(
  values: Readonly<Record<string, string | undefined>>,
  run: () => Promise<T>,
): Promise<T> {
  const original = new Map<string, string | undefined>();
  for (const key of Object.keys(values)) original.set(key, process.env[key]);
  try {
    for (const [key, value] of Object.entries(values)) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
    return await run();
  } finally {
    for (const [key, value] of original) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
  }
}
EOF
node <<'NODE'
const fs = require('node:fs');
const p = 'src/features/release-commands/tests/release-commands.test.ts';
let s = fs.readFileSync(p, 'utf8');
const anchor = 'import path from "node:path";\n';
s = s.replace(anchor, anchor + 'import { withTemporaryEnvironment } from "@/core/config/test-env";\n');
const start = s.indexOf('const SYNTHETIC_RUNTIME_KEYS = [');
const end = s.indexOf('\n\nasync function main()', start);
if (start < 0 || end < 0) throw new Error('synthetic runtime helper block missing');
const replacement = `async function withSyntheticDevelopmentRuntime<T>(run: () => Promise<T>): Promise<T> {\n  return withTemporaryEnvironment({\n    NODE_ENV: "development",\n    ASOL_MODE: "development",\n    NEXT_PUBLIC_ASOL_MODE: undefined,\n    VERCEL: undefined,\n    VERCEL_ENV: undefined,\n    ASOL_DATA_SOURCE: "local",\n    ASOL_PROVISIONING: undefined,\n    GITHUB_ACTIONS: undefined,\n  }, run);\n}`;
s = s.slice(0, start) + replacement + s.slice(end);
fs.writeFileSync(p, s);
NODE
